NIGHT_LOADED({"seed":1044,"generated_at":"2026-10-21T06:00:00Z","chain":[1,4,2,3,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":6,"drawers":[{"id":"1-1","type":"P2","difficulty":2.9387,"rank":0.0523,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV001201","role":"target","render":{"description":"Voorspellingen dat zieke man zal genezen, eerst met wit paard en later met zwart paard ploegen, en dat het zwarte paard de lijkwagen zal trekken, komen uit. De paarden die eerst voor de lijkwagen worden gespannen weigeren, zodat het zwarte paard moet worden ingespannen.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43204","original":"Voorloop. \nSchoenmaker vertelt.\n\nOal Kamies noast ons was de haile winter al aon 't sukkeln.\n't Gung dan veur-, dan achteroet,\nBuurman Wessels was 't er op 'n dag hèn west te kieken, hou d' oale 't muik.\n\"Kamies gait achteroet, hai hoal 't nich meer,\" zee hai.\nMoar opa, oal Steffen, zee.\n\"Nee Wessels, Kamies wordt weer beter.\nHai hef nou 'n wit peerd. En 't volgend veurjoar plougt hai 't land mit 'n zwaarde. \nDat zwaarde peerd brengt hum vot.\" \n't Widde wör verkoft en 'n zwaarde kwam d'r veur in de ploats.\nEen buurman hef hiermit de grond pluigd.\nVolgende zömmer störf Kamies.\nVeur de woagen zol 'n peerd van de buren.\nKamies zien aigen har er nog nooit veur west en doarum wol ze hom laiver nich broeken. …","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV000905","role":"helper","render":{"description":"Voordat er een weg is horen van geluid van een hondekar en blaffen van honden.","place":"Ter Apel","prov":"Gr.","year":1962,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43087","original":"Maar wel is het waar, dat veel mensen in het veen een hondekar hebben horen ratelen. Ook hoorden ze de hond blaffen.\nLang voor er een weg was en voor er later inderdaad een hondekar langs trok.","lang":"Standaardnederlands","front":"original"},"home":"1-1","geo":[52.87667,7.05972]},{"id":"c3","story_id":"WEV006906","role":"helper","render":{"description":"Voorspelling dat er eens veel soldaten zouden komen met wagens zonder paarden. Bij de intocht van de Candadezen in 1945 herinnert iemand zich dit.","place":"Vriescheloo","prov":"Gr.","year":1963,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43580","original":"Veurloop.\nt Is n hail zet leden. Oabram zee es n moal: “Hier koomt nog ais n haile bult seldoatn. Ik zai ze bie t hoes van H. en bie K en op t haim van Z. Zai hebt woagens bie zuk zunder peerden.\n Toun in 1945 de Canadezen kwamen, was dr nog aine oale, dei zuk dat vertelsel van de spoukkieker in t zin schoot. Hai lag op berre en kun nait best wat zegn, omdat e verlamd was. \nMoar zoveul begreepn wie wel van zien “hoi, hoi”, dat e zegn wol:“Oabram zee t ja al?”","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.06833,7.11389]},{"id":"c4","story_id":"WEV008709","role":"helper","render":{"description":"'s Avonds lawaai in de paardestal is voorteken dat paard iets kapot zal trappen.","place":"Wessinghuizen","prov":"Gr.","year":1965,"code":"SINSAG 0487","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/45305","original":"t Gebeurde wol is, dat ze s oavends wat in t peerdstaal heurden. Kiekn deden ze maistied nich, man ze wuzzen wol, dat t peerd gauw wat stukn hou-en zol; door was t n veurbeduudsel van.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.0525,7.075]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessinghuizen.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.2386,"rank":0.4673,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ051006","role":"member","render":{"description":"Een vader waarschuwt zijn kinderen 's nachts nooit middenop de weg te lopen. Ze kunnen immers op een lijkstoet stuiten.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25083","original":"Heit woe noait lije, dat wy froeger by jountiid of by nacht midden op 'e wei roannen. Sels gong er ek altyd yn 'e berm lâns. Men koe ris tsjin in lykwein oprinne, wie syn sizzen altyd.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"KOOIJMAN2266","role":"intruder","render":{"description":"Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","place":"Heesselt","prov":"Gld.","year":1963,"code":"SINSAG 0333","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127631","original":"Dat weet ik ook nog. Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","lang":"Standaardnederlands","front":"original"},"home":"cab:4"},{"id":"c3","story_id":"CJ112406","role":"member","render":{"description":"Vanwege lijkstaties die de ruimte nodig hebben is het goed om 's nachts niet midden op de weg te lopen.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/30112","original":"Noait mat men by nacht midden op 'e wei rinne, fanwegen in lykstaesje, dy't altyd paed ha mat en dy't dan wolris tsjin jin oanstompe kin.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c4","story_id":"CJ034606","role":"member","render":{"description":"Je moet nooit middenop de weg lopen, omdat je opzijgedreven kan worden door een lijkstoet.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22678","original":"Der woarde ús al hiel jong leard, noait midden op 'e wei to rinnen. Hwant it koe gebeure dat der in lykstaesje oankom en dan woarde men oan kant set.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Heesselt hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":4},"on_success":{"trail_note":0,"unlock_cabinet":4,"stack":["c1","c3","c4"]}},{"id":"1-3","type":"R1","difficulty":1.0929,"rank":0.0377,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"WEV009205","role":"omen","render":{"description":"Wie met de helm geboren is kan vooruitzien. Als de helm meteen begraven wordt is er niets aan de hand.\nVrouw bewaart zes helmen van overleden kinderen.","place":"Onstwedde","prov":"Gr.","year":1965,"code":"TM 2901","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44560","original":"Mit helm geboorn.\nKiek, wel mit helm geboorn is, kan veuroet zain; hai wordt spuikkieker. As de helm onmiddelk in de grond stopt wordt, is dr niks an de hand, man anders worden t bezundere mensn.\nEn leuft ais, dat dat nich zo mooi is.\nDou k in dainst was, kwam ik wol ais bie n vrouw in hoes, dai zes helms in de kaaste lign har. Dai wazzen van zes kinder, dai allemoal overleden warn; man de helms har t oal mens opbaargt. Zai wol ze mie wol ais zain loatn, man door har ik ja gain belang bie.\nt Wazzen dreuge vliezn. In de vörm van n haalve bolle.","lang":"Gronings","front":"description"},"home":"1-3"},{"id":"c2","story_id":"WEV013104","role":"omen","render":{"description":"Lijk dat zondag overstaat betekent binnen zes weken weer een sterfgeval .","place":"Bellingwolde","prov":"Gr.","year":1966,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44380","original":"n Volksgeleuf was wieder, dat as ain liek n zundag overstun, dat er den binnen zes weekn weer ['n] staarfgeval komen zol.","lang":"Gronings","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CBAK0041","role":"omen","render":{"description":"Voorspelling dat een kind niet oud zal worden. Het kind sterft inderdaad op zes-jarige leeftijd.","place":"Broek in Waterland","prov":"N.-H.","year":1899,"code":"SINSAG 0489","initials":"C.B.","url":"https://www.verhalenbank.nl/items/show/8638","original":"Grietje Holleman heeft tegen een broertje van een Broeker dame gezegd dat hij niet oud zou worden. Op zes-jarige leeftijd is hij overleden.","lang":"Standaardnederlands","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","6 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":6},"on_success":{"chime":6,"digit":{"value":6,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":3,"drawers":[{"id":"2-1","type":"P6","difficulty":3.2223,"rank":0.3953,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"CBOEK305","role":"clip1","render":{"description":"Een andere spookgeschiedenis vertelt over een witgesluierde dame die tussen twaalf en een uur door de muur heen komt. Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","place":"Driebergen-Rijsenburg","prov":"Utr.","year":1892,"code":"SINSAG 0301","initials":"M.R.v.d.V.","url":"https://www.verhalenbank.nl/items/show/34810","original":"Een Spookgeschiedenis\nEen spookgeschiedenis zooals deze is er nog een, waarin eene geheimzinnige witgesluierde Dame het spook is; welke eveneens tusschen 12 en 1 uur komt, maar door den muur heen in de slaapkamer en roept, (wanneer zij iemand in de kamer ziet, welke het spook dooden wil), met een holle, nare grafstem: \"Wie stoort hier mijn rust?\" Daarop loopt zij toornig op den bevenden man toe en draait hem den hals om; daarna verdwijnt zij weer door den muur, alhoewel er geen deur in is. Nu durft niemand meer te wagen op het kasteel een nacht te slapen; totdat er eindelijk een moedige sterken man komt, op 't slot des nachts gaat en de witte Dame voor altijd verdelgt...\n(Breedvoerig ken ik deze historie niet meer.)","lang":"Standaardnederlands","front":"description"},"home":"2-1"},{"id":"c2","story_id":"CJ006515","role":"clip2","render":{"description":"Op de Lytse Wei spoken twee witte vrouwen. In het donker gaat men er niet langs.","place":"Harkema","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/16867","original":"Op 'e Lytse Wei spoeken twa wite wiven. Yn 't tsjuster doarsten se dêr net lâns.","lang":"Fries (Woudfries)","front":"description"},"home":"2-1"},{"id":"c3","story_id":"LINSSEN009501","role":"clip3","render":{"description":"Ontmoeting met juffrouw zonder kop; opgraven van drie kisten met schatten mislukt door verbreken zwijgen.","place":"Diergaarde","prov":"L.","year":1965,"code":"SINSAG 0310","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208983","original":"Juffrouw zonder kop.. De paardeknecht van de boerderij \"de Horst\"onder de gemeente Echt, kwam 's avonds eens van de kermis thuis. Hij was over de grens geweest op Gulichs gebied en keerde door de bossen van \"de Doort\" terug. Hij had rijkelijk veel gedronken, raakte de weg kwijt en besloot maar te gaan liggen en de volgende morgen af te wachten. Juist hoorde hij de torenklok van Echt twaalf uur slaan en daarop aansluitend sloeg de klok van Dieteren (Susteren) ook twaalf. Dus Driekus, de knecht telde 24 slage n \"Zo laat ben ik nog nooit thuisgekomen\", dacht hij, \"wat is het hier toch een gekke boel, zowel met de weg als met de tijd.\"\nNauwelijks was hij ingeslapen of hij werd wakker door een vreemd geluid. …","lang":"Standaardnederlands","front":"description"},"home":"2-1"},{"id":"c4","story_id":"CJ053309","role":"inside","render":{"description":"Een man ziet 's nachts plotseling twee witte vrouwen. De twee vrouwen nemen plaats op zijn wagen. De man wordt zo bang, dat hij er snel vandoor gaat.","place":"Ons Belang","prov":"Utr.","year":1968,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25339","original":"Hjir ien út 'e Harkema ried us mei de boerewein op in nacht nei Readskuorre ta. Doe seach er dêr ynienen twa wite froulju foar him. Hy ried dêr mei de hynders lyk op yn.\nDoe kommen dy beide froulju yn 't wyt by him op 'e wein.\nHy woarde sa binaud, dat hy sette sokken en naeide út.","lang":"Fries (Woudfries)","front":"original","note":"Deze bewaar ik apart."},"home":"2-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 12.","12 — 2 — 3."],"lock":{"kind":"number3","salt":"f49b6b07e38cc148","accepted_hashes":["14d00cdfe8f2791000ca7966bbd20b524114e142d471521f8c053e25e849550d"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"2-2","type":"P3","difficulty":1.2302,"rank":0.7455,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ029903","role":"intruder","render":{"description":"Een bruidspaar is op weg naar het gemeentehuis, als de aanstaande bruidegom zijn bruid ineens een stuk uit het schort bijt. De man is een weerwolf; het meisje maakt het terstond uit.","place":"Kûkherne","prov":"Fr.","year":1953,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21918","original":"It gebeurde us dat twa jonge lju yn 'e wein sieten nei 't gemeentehûs ta. Hja soenen dy deis trouwe. Underweis yn 'e wein byt de man har in stik út 'e skelk. Hy wie in wjerwolf. Hja makke it fuort út.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:3"},{"id":"c2","story_id":"CBOEK477","role":"member","render":{"description":"Een knecht moet in een weddenschap aantonen, dat hij de spit in de Witte Wieven-kuil durft te gooien. Hij gooit en daagt het witte wief uit, dat hem achtervolgt. Met paard en al springt de knecht over de onderdeur. Het witte wief gooit de spit, dat in de middelaar van de deur blijft zitten.","place":"Bathmen","prov":"Ov.","year":1892,"code":null,"initials":"J.V.","url":"https://www.verhalenbank.nl/items/show/39631","original":"In de buurtschap Loo, op het erve Noever ging men een weddenschap aan met een knecht, dat hij het spit niet durfde gooien in de Witte-wieven-kuul; deze bevond zich daar ergens in de buurt. Hij sprong te paard en joeg derwaarts, aldaar smeet hij het spit in de kuil met de woorden:\n\nWit wieven wit\nHier breng ik oe een spit\n(of: Wat heb ie'j op oe spit?)\n\nDaarop had het wit wief gezegd:\n\nA'j zoo lang wacht\nDak mien eene schoe toeknuppe\nEn de aander toerukke\nDan zal ie'j 't gebraad wezen.\n\nDe knecht rende toen in vliegenden vaart huiswaarts, achtervolgd door het wit wief en voor de achterdeur gekomen, was de bovendeur los en de onderdeur dicht, maar het paard was nogal vlug en sprong over de onderdeur. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"LYST279","role":"member","render":{"description":"Een boerenknecht brengt het spit naar de Witte Wieve. Een van hen achtervolgt hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel. Het Witte Wief kon niet sneller lopen, omdat ze problemen had met een van haar schoenen.","place":"Tilligte","prov":"Ov.","year":1937,"code":null,"initials":"B.R.","url":"https://www.verhalenbank.nl/items/show/13623","original":"Door ouden wordt nog van de Wit Wieve verteld, die alleen kwaadaardig waren, wanneer ze getergd werden. Zo wordt verteld dat een boerenknecht eens het spit bracht naar de plaats, waar zij woonden. Hij werd door eene der witte wieve achtervolgd, doch hem niet kon inhalen, omdat ze in de haast maar een schoen had kunnen aantrekken. Toen de knecht het huis binnenvluchtte, wierp ze hem met een bijl achterna, die in de steil (deurpost) terecht kwam.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"ENGELB_15_003","role":"member","render":{"description":"Over bestaan van witte wieven en spit in deurpost.","place":"Geesteren","prov":"Ov.","year":1979,"code":null,"initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128566","original":"H.E.: Van de witn wiew he’j doar wa mangs van heurd?\nVr.Vr.: Van de witn wiew is ok niks van woar.\nH.E.: Nee, mer te geet ok um t verhaal, he. Joa he’j hier nog zonnen beuld, zonnen witn wievnbeuld. Ne, nee, nee (door elkaar heen gepraat, ze zijn het met elkaar niet eens)\nVr. [Wolberink, Jan]: Wat hadn ze bie ouns ok zegd, oh jee no valt mie t kenneke in zee Dat stun nog moal vuur joarn in de Twentse kraant. Als ik t met ene schoen had vastgebondn, gevondn als de ander gebondn.\nA.Ve.: ... t spit nog in n stiel van n nienduur nog zitn.\nF.Ve.: t Spit brengn.","lang":"Twents","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Kûkherne hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":3},"on_success":{"trail_note":2,"unlock_cabinet":3,"stack":["c2","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0901,"rank":0.7966,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"CJ005402","role":"card","render":{"description":"De vader van de vertelster ging eens om één uur in de nacht van Sânbulten terug naar Zwaagwesteinde. In het Zwagerbosch zag hij ineens vijf vrouwen staan met puntmutsen op en lange witte rokken aan. Het was bladstil maar de pluimen van de mutsen waaiden heen en weer. Hij werd doodsbenauwd en ging naar de boerderij van de oude Bearn. Toen ze samen gingen kijken waren de vrouwen weg.","place":"Buitenpost","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/16510","original":"Heit hat us in kear nei de Sânbulten to praten west. Om ien ûre yn 'e nacht gong er werom nei de Westerein ta. Op Sânbulten moest er oer 't spoar en sa kom er troch Sweagerbosk. 't Wie blêdstil en moai sacht waer. Der wie neat dat him forroerde.\nDoe seach heit dêr yn Sweagerbosk ynienen fiif froulju stean, allegear mei in puntmûtse op en lange wite rokken oan. Hoewol it blêdstil waer wie, waeiden de tûfen [fan] de puntmûtsen al mar hinne en wer. Heit wie deabinaud. Hy gong nei âlde Bearn op 't hiem en kloppe dêr op 'e achterdoar. Hy kloppe Bearn der út. Hy fortelde Bearn mei in triljend lûd hwat er sjoen hie. Doe gong Bearn mei him om nei dy froulju to sjen. Mar doe wie der net ien mear. Doe't heit yn 'e Westerein oankom, trille er noch.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c2","story_id":"CJ034801","role":"card","render":{"description":"Op een spookplaats spoken witte juffers.","place":"Oudega","prov":"Fr.","year":1968,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22700","original":"Us mem biwearde, to Aldegea spoeke it op in smel reedtsje by Jan Japiksma. Dêr wie in boskje mei in gracht der omhinne. Dêr spoeken wite juffers.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c3","story_id":"YPFOE070a","role":"card","render":{"description":"Op een kruispunt vlak bij Jistrum spookte het 's nachts. Een van Durk Jaringa's zonen kwam 's avonds na een feestje bij dat kruispunt langs en zag een witte gestalte vlak voor zich heen zweven. Hals over kop rende hij terug naar Jistrum. Een paar anderen hebben hem later langs het kruispunt naar huis gebracht, maar van de gestalte was niets meer te zien.","place":"Burgum","prov":"Fr.","year":1972,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12146","original":"Wite juffers\nTe Jistrum, oan 'e noardkant, dêr krúst de Spoekloane de wei dy't fan Jistrum nei de Grinzerstrjitwei rint. Op dat krúspunt doogde it lang net. Dêr gong wol ris in wite gestalte dwers oer de wei, flak foar de minsken lâns. Ik wit noch wol, dat ien fan Durk Jaringa's jonges-se wennen oan 'e grutte strjitwei- de jûnes nei 'De Lindeboom' yn Jistrum west hie - sa hiet de jachtweide fan Jan van der Schors. It hie der tige gesellich west, hy hie in slokje dronke en om in oere of tsien, alven sette er op hûs yn. Hy kaam dêr op dy fjouwersprong en dêr gong dy wite gestalte flak foar him lâns. Hy waard sa kjel, dat hy stode hals oer de kop wer nei Justrum ta en dêr fûn er andergeloks noch lju yn 'e herberch. …","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c4","story_id":"ZEEUW047","role":"card","render":{"description":"'s Nachts verschijnen van een witte vrouw en verdwijnt in een put. Na het dempen van de put verschijnt ze niet meer.","place":"Yerseke","prov":"Zl.","year":1923,"code":"SINSAG 0310","initials":"G.D.v.O.","url":"https://www.verhalenbank.nl/items/show/38973","original":"Witte Juffers\nOok te Ierseke verscheen de Witte Vrouw op een stuk grond tusschen Lepel- en Mosselstraat. Later heeft men uit de voorwerpen die daar gevonden zijn, kunnen nagaan dat dit opgehoogde terrein in de oudheid als kerkhof heeft gediend, en vermoedelijk ook een vluchtheuvel was.\nVele omwonenden hebben haar, in het holle van den nacht, gezien. Ze verdween dan altijd in een diepe welput. Na het dichten van de put, kwam de witte vrouw niet weer. Ze had rust gevonden.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c5","story_id":"CJ063612","role":"card","render":{"description":"In Almelo hebben ze witte wijven en er spookt een mooie vrouw. Dat heb ik gehoord toen ik daar paarden kocht.","place":"Soesterberg","prov":"Utr.","year":1969,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27090","original":"In Almelo hebben ze witte wiven. En daar spookt ook nog een mooie vrouw om. Ik heb het daar wel eens gehoord toen ik daar peerden kocht.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ018012","role":"sill","render":{"description":"Op een spookplaats spoken altijd drie witte dames, zusters, rond. Later zou die plaats ook de 'Susterwei' heten.","place":"Garyp","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20251","stain":"drie"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een G.","Garyp. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c6","object":"window","text":"Garyp"},"on_success":{"digit":{"value":3,"card":"c6","word":"drie","stained":"c6"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P4","difficulty":1.8646,"rank":0.9828,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"CBOEK091","role":"top","render":{"description":"Een jongeman is een weerwolf. Wanneer hij wandelt met zijn meisje, voelt hij aankomen dat hij zal veranderen. Hij stuurt haar verder en waarschuwt haar voor een grote hond. Zij moet hem zijn zakdoek toewerpen, dan kan het meisje vluchten.","place":"Bladel","prov":"N.-Br.","year":1894,"code":"SINSAG 0823","initials":"J.F.C.S.","url":"https://www.verhalenbank.nl/items/show/13127","half":"top"},"home":"3-1"},{"id":"c2","story_id":"LYST027","role":"distractor","render":{"description":"Op een verjaardag laten ze hem niet vertrekken. Opeens valt er een wolfsvel uit de schoorsteen in het vuur. Het verbrandt en de jongeman is verlost.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"},{"id":"c3","story_id":"ZEEUW181","role":"distractor","render":{"description":"Toen ze het vel in de oven gooiden, kwam hij schreeuwend aangerend, maar toen het verbrand was, was hij blij, dat hij er vanaf was.Ze waren erachter gekomen, dat hij de weerwolf was, doordat ze de wolf een blauwe schort toewierpen; de volgende dag had de knecht blauwe rafels tussen zijn tanden.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"},{"id":"c4","story_id":"LYST198","role":"distractor","render":{"description":"Wanneer de wandelaar thuiskomt, weet zijn familie door die bloedneus gelijk dat hij een weerwolf heeft gedragen. Meestal zijn de slachtoffers van een weerwolf stropers of smokkelaars, die 's nachts hun beroep uitoefenen.","half":"bottom","code":"SINSAG 0801"},"home":"3-1"},{"id":"c5","story_id":"CBOEK490","role":"distractor","render":{"description":"Er komt dan een berenvel door de schoorsteen zakken, dat moet hij aandoen en 's nachts het dorp doorgaan. Zijn vader, die nu dood is, moest het vroeger doen.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"},{"id":"c6","story_id":"VVUNL315","role":"distractor","render":{"description":"Tis de smid sleept de rugplakker, hem bij de poten vasthoudend, naar Sjaaks café, waar hij de deur openbonst en rappe Peerke het monster een haal geeft, zodat het bloed uit zijn kop stroomt en de knecht van de \"Beese\" (een boerderij uit de omgeving) er staat, die meteen wegrent, waarna men van de weerwolf niet meer hoorde.","half":"bottom","code":"SINSAG 0801"},"home":"3-1"},{"id":"c7","story_id":"LYST236","role":"distractor","render":{"description":"Wanneer de ongelukkige aan het kaart spelen is, blijft iedereen net zolang zitten totdat het twaalf uur wordt. De betoverde man wordt steeds zenuwachtiger, maar iedereen blijft gewoon zitten. Om klokslag twaalf uur rolt het vel van de weerwolf door de schoorsteen naar binnen en wordt onder luid gejuich in de openhaard verbrand. De man is van de betovering verlost.","half":"bottom","code":"SINSAG 0824"},"home":"3-1"},{"id":"c8","story_id":"LYST024","role":"distractor","render":{"description":"Zijn vrienden willen een grap met hem uithalen en sluiten alle ramen en deuren. Na een half uur verandert de man in een weerwolf. Zijn vrienden vluchten, maar een dappere rietdekker steekt de weerwolf. De man is nu verlost.","half":"bottom","code":"SINSAG 0822"},"home":"3-1"},{"id":"c9","story_id":"CBOEK091","role":"bottom","render":{"description":"Later zien zij en haar familie echter dat de stukken zakdoek tussen de tanden van de jongeman zitten. Weerwolven hebben altijd een band om hun middel. De boer, bij wie de jongeman in dienst is, verbrandt de band. De weerwolf probeert nog in het vuur te komen, maar hij wordt tegengehouden. Wanneer de band verbrand is, is de jongeman weer een gewoon mens.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c10","story_id":"CJ017409","role":"distractor","render":{"description":"De man maakt zich snel uit de voeten, maar zijn vrouw volgt hem. Ze ziet dat de man de rok verscheurt met zijn tanden; het schuim staat hem om de mond. De man bekent haar dat hij een weerwolf is en dat hij wel in een doek moest bijten, omdat hij anders een mens zou moeten aanvallen. De vrouw zegt terstond het huwelijk af.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"},{"id":"c11","story_id":"TINNEV032","role":"distractor","render":{"description":"De knecht ligt op zijn rug, met zijn mond open, waar op een gegeven moment een mol uit komt kruipen. Deze mol gaat achter de koeien in het weiland aan en kruipt dan weer terug. De knecht rekt zich uit en staat op. Maar dan moet hij overgeven. De dagloner ziet dat hij bloed uitbraakt. De knecht gaat naar huis en de dagloner gaat het gras zaaien. Later vertelt de boer dat er een kalf verdwenen is. Als de knecht overleden is, is de kist zo zwaar, dat niemand hem op kan tillen. Ook de dominee kan hier niets aan doen. Men haalt de pastoor erbij. Deze bindt een touw aan de kist en trekt hem van zijn plaats. De kist kan nu wel opgetild worden om naar het kerkhof gebracht te worden.","half":"bottom","code":"SINSAG 0804"},"home":"3-1"},{"id":"c12","story_id":"KOOIJMAN1308","role":"distractor","render":{"description":"Mijn opa vertelde eens dat een visser werd aangevallen door een weerwolf, maar toen hij hem in elkaar sloeg en stak met een mes, liep die man de volgende dag in het verband.","half":"bottom","code":"SINSAG 0822"},"home":"3-1"},{"id":"c13","story_id":"BROUWERS002507","role":"distractor","render":{"description":"Weerwolf komt op meisje af, dat het doosje naar hem gooit. Weerwolf verdwijnt, jongen komt terug.","half":"bottom","code":"SINSAG 0823"},"home":"3-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het onderste stuk noemt ‘zakdoek’ opnieuw.","Het nummer is SINSAG 0823. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c9"},"on_success":{"fuse":["c1","c9"],"stack":["c1","c9"]},"found_card":{"card":"c9"}},{"id":"3-2","type":"P3","difficulty":1.2475,"rank":0.7798,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ015102","role":"intruder","render":{"description":"Een ongeduldige, ruwe boer wil voor de avond een groot stuk land omgeploegd hebben. De knecht vertikt het en zegt de boer dat hij maar naar de duivel kan lopen met zijn voorstel. De boer vat dit letterlijk op en schakelt de hulp van de duivel in. De volgende morgen is het land omgeploegd. Zijn dwepen met de duivel is de boer duur komen te staan: op zijn sterfbed werd hij door de duivel opgehaald.","place":"Hurdegaryp","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19770","original":"Der wie in boer, dat wie in forwoesteling. Hy wie altyd gleonhastich en net in arbeider dy't it by him úthâlde koe. Op in kear hied er wer in arbeider, doe moest der ploege wurde. It wie al let yn 'e joun en it wie ûnmooglik dy greate hoeke lân foar de nacht noch to ploeijen. Dat de arbeider sei tsjin 'e boer: \"Freegje de duvel, dat dy it docht.\" De boer sei: \"Dat dog ik\" en hy die it ek.\nDe oare moarns wie it stik lân ploege.\nMar hy hat it sûr bikeapje matten. Doe't er op syn stjerbêd lei, hat de duvel him helle.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c2","story_id":"VVUNL049","role":"member","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":null,"initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"ENGELS000115","role":"member","render":{"description":"Weerwolf bespringt 's avonds mensen; als helper bij werk; verandering in weerwolf door aantrekken verborgen jas, na verbranden jas bevrijding.","place":"Helden","prov":"L.","year":1962,"code":null,"initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/57969","original":"Weerwolven:\nMannen, die wat laat op de baan waren, werden, vooral in donkere, stormachtige nachten soms besprongen door de weerwolf. Dit spookdier met gloeiende ogen sprong hen op de rug, en klemde zich met de voorpoten om hun nek. Ze bleven zich als een zware last aan de verschrikte man klemmen totdat hij ergens een huis bereikte. In de Broekbeemd, tussen Onder-Eijndt en Zandberg, stond ergens een holle eiken knot of poesjt. Er was een man, die als weerwolf bekend werd. Hij had een aparte jas; als hij deze aantrok werd hij weerwolf. Na zijn nachtelijke tochten verborg hij deze jas in die holle “poesjt”. Zijn buurlui ontdekten dit, en staken de “poesjt” met de jas in brand. …","lang":"Standaardnederlands; Limburgs","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"KEMP298","role":"member","render":{"description":"Een pachter komt erachter dat een kleine scheper op zijn boerderij vermoedelijk een weerwolf is. Hij stuurt hem weg voor een dag en hij en zijn knechten ontdekken in een holle wilg een wolvenvel. Ze steken het thuis in brand. De scheper keert vervolgens in razend tempo terug en wil zijn vel teruggrijpen. Als dat niet lukt, vlucht de scheper naar de holle boom en is nooit meer teruggezien.","place":"Broek","prov":"L.","year":1925,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43423","original":"Het weerwolfsvel verbrand\n\nBij de pachter van de boerderij bij het kasteel Geusselt onder Amby diende eens een scheper, een klein manneke, dat de naam had een weerwolf te zijn. 's Nachts was hij nooit in bed te vinden, maar 's morgens lag hij er weer in. De knechts van de hoeve hadden dat al dikwijls bemerkt.\nWijl dit zo opvallend was, werd zijn doen en laten gedurig bespied en zo bemerkte men dan ook dat hij, wanneer hij 's avonds uit zijn bed kroop, naar een weide ging, waar heel eenzaam een grote holle wilg stond. Daar verdween hij iedere keer in.\nOm het fijne van de zaak te achterhalen stuurde de pachter hem op zekere namiddag naar een dorp, dat meer dan drie uur van de hoeve lag, om daar koeien te kopen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Hurdegaryp hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c2","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.079,"rank":0.6923,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"TINNEV043","role":"card","render":{"description":"Twee mannen zijn grasstengels aan het snijden, als de ene man aan de andere vraagt of hij hem eens wil zien. Meteen daarop ligt er een wolf in het gras. De man wil nooit meer met de ander werken.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0804","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22389","original":"30.\nOp een andere kier vroeg Dorus aan Peter, toe ze aan 't smele sui'je ware: \"Wi'j um is zien?\" Medeen derop lei een grote wolf ien 't gres. Peter wol van toe af aan de niet meer met Dorus op uut.","lang":"Liemers","front":"description"},"home":"3-3"},{"id":"c3","story_id":"LYST008","role":"card","render":{"description":"Een boerenknecht haalt iedere nacht precies om twaalf uur een hoepeltje uit de lindeboom. Hij hangt de hoepel om zijn nek en verandert in een weerwolf. Hij loopt een tijdje rond en verscheurt alles wat er in zijn buurt komt. Hierna wordt hij weer gewoon mens. De boer vindt zijn gedrag maar vreemd en vraagt raad aan de pastoor. De pastoor heeft door dat de boerenknecht een weerwolf is, en adviseert de boer om de knecht een boodschap te laten doen waarbij hij nooit om middernacht weer thuis kan zijn. Op de afgesproken nacht haalt de pastoor om middernacht de hoepel uit de boom. De knecht staat onder die boom en ziet alles. Hij vlucht en komt nooit meer terug.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0803","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13222","original":"De Weerwolf\nEen boerenknecht kroop 's nachts klokslag 12 uur in de lindenboom voor de boerderij. Boven in de boom hing voor gewone mensen onzichtbaar een hoepeltje. Dat hing de knecht om zijn hals. Als ie uit de boom geklauterd was, liep ie in de gedaante van een hond weg en verscheurde alles wat hem in de weg kwam. Als ie een tijd zo rondgelopen had, was ie weer gewoon mens. Na een tijd was het de boer, bij wie de weerwolf in dienst was, opgevallen, dat zijn knecht nacht op nacht weg was. Hij ging naar de pastoor en die had het zaakje meteen door. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"CJ039818","role":"door","render":{"description":"Een van zeven op elkaar volgende zonen is een weerwolf.","place":"Harkema","prov":"Fr.","year":1968,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23535"},"home":"3-3"},{"id":"c5","story_id":"LYST189","role":"card","render":{"description":"Drie mensen vertellen dat zij 's avonds laat een grote hond met vurige ogen zijn tegengekomen, die bij hen op de rug sprong. Pas bij de grens van het stuk land sprong hij eraf en verdween. De hond verdween bij een boerderij die al als \"niet pluis\" bekend stond, omdat de knecht van die boerderij vertelde dat de koeien enkele malen om klokslag middernacht opsprongen terwijl de staldeuren vanzelf opensprongen.","place":"Puiflijk","prov":"Gld.","year":1957,"code":"SINSAG 0801","initials":"C.v.d.P.","url":"https://www.verhalenbank.nl/items/show/13453","original":"Spookdieren\nMij is eens door drie verschillende personen op zeer verschillende tijden meegedeeld dat op de Waaldijk tussen Boven-Leeuwen en Druten 's avonds in pikdonker plotseling een abnormale grote hond, die plotseling verscheen, hen zwijgend met vurige ogen volgde en even plots aan de grens van Druten verdween. Beide personen waren niet bijgelovig maar hadden van angst 't zweet op de rug staan van angst, temeer daar de hond verdween bij een boerderij waar 't niet \"pluis\" scheen te zijn. Een knecht op deze boerderij vertelde mij eens hoe verscheidene malen 's nachts de koeien om klokslag 12 uur opsprongen en staldeuren openvlogen zonder 'n aanwijsbare oorzaak. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c4","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c1"},"stack":["c1","c2","c3","c5"]}}]},{"id":4,"label":"Spoken","digit":2,"drawers":[{"id":"4-1","type":"P5","difficulty":0.6696,"rank":0.25,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"WEV009505","role":"variant","render":{"description":"Om middernacht spookt geest van een vermoorde rond en spat het bloed op op de plaats van de moord. Jongen durft dan niet over de rechterschouder te kijken.","place":"Stadskanaal","prov":"Gr.","year":1965,"code":"SINSAG 0450","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44586"},"home":"4-1"},{"id":"c2","story_id":"WEV015701","role":"variant","render":{"description":"'s Avond laat merkt man dat achterdeur van stal open is en hoort gestommel, dat niet van de koeien komt. Boer vertelt dat vrouw die er is vermoord zo nu en dan spookt.","place":"Musselkanaal","prov":"Gr.","year":1967,"code":"SINSAG 0450","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/45797","original":"Mien voader kon kwoad zain en hef mie door veul van verteld. Hai dainde as jongkerel bie de boer. Op n keer kwam e wat loat in hoes. Dan gung e deur de achterdeure van de dele, umdat andere deurn dicht zatn. As hai dan dele opstapt, heurt hai n geluud, man zug niks. \n“Kou lös”, denkt e. Hai zöcht n schienvat op en gait de baistn bie langs. Man nee heur, alles is rustig. \n Zeker wat verbeeld, zo denkt hai. Nich laank loater overkomp hum t zulfde; weer gestommel op dele en t binnen gain koi-en, dai t doun. \nNon wait hai nich meer, wat e door van denkn mout. Wol wait hai wizze, dat e nooit meer deur de baanderdeure wil. \nAnder dag under t eetn proot hai dr over mit de boer. Dai zeg eerst niks. …","lang":"Gronings","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ105507","role":"variant","render":{"description":"Men kan 's nachts wel eens een witte verschijning van een vermoorde vrouw zien.","place":"Opende","prov":"Gr.","year":1973,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37578","original":"Mem fortelde, hjir yn 'e Pein hat in huzinge stien mei in gracht der by. Dêr is alris in frommeske formoarde woarn. Sûnt seach men dêr nachts in frou yn 't wyt troch de gracht hinne rinnen. Dat wie dat formoarde frommeske.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Groningen werd een tijdstip genoemd: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"4-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1965.","Op die kaart staat een tijdstip. Welk?"],"lock":{"kind":"word","salt":"f49b6b07e38cc148","accepted_hashes":["031aa5a44117318c98592f7eb5d6f378537e3570555c03b30f754963c67d5e01","1bc28a0ec7a57388d5425fa254504bc07339fd62a7ae75b48e9f9f8955709fbd","7491c020e6ad7c30f397c99a3fd0196f26a86662875fa9d1533d98968fa4541b","9558e4466998a437b7e71e6de72150e105509854285b30f0d9c79ed43a8df173"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.212,"rank":0.7143,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ015603","role":"intruder","render":{"description":"Een visser ziet een juffer in witte kleren en besluit haar te volgen. Het witte wief verdwijnt echter even snel als ze verschenen is.","place":"Broeksterwâld","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19893","original":"Douwe syn broer Anne Feddema hie to fiskjen west. Hy hie nei 't tichtset ta west en farde de Lyts út wei werom de kant nei de brêge út. Doe kom der in juffer oan yn sniewite klean. Hy tocht: Ik wol wite hwer't dy keart, dat hy hie 't eech net fan har ôf. Doe't er oan har ta wie, died er de fêstsetter yn 'e kant en krekt doe't er dat die, wie de wite juffer fuort.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c2","story_id":"DYKFRIES2153","role":"member","render":{"description":"Op de Leppedijk spookte een gloeiend veulen rond. Een boerenmeid was tot laat in het dorp gebleven en moest alleen naar huis. Toen ze gewaarschuwd werd voor het spookveulen, beweerde ze dat ze het dier haar kousenband in de bek zou doen en op het beest naar huis zou rijden. Toen ze het dier echter daadwerkelijke ontmoette, schrok ze hevig en rende ze naar huis.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69329","original":"Op den Leppedijk, niet ver van Oldeboorn, spookte voorheen een gloeiend veulen. Eene boerenmeid was op zekeren avond wat laat in het dorp gebleven en toen haar gezegd werd, dat het veulen haar wel kon ontmoeten, zei ze, dat zij hem dan haar kouseband in den bek zou doen en op hem naar huis rijden. Maar toen zij, op den weg gekomen, het veulen eensklaps vóór zich zag met den bek wijd opengesperd, toen liep zij zoo hard zij kon om tehuis te komen.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"DYKFRIES2191","role":"member","render":{"description":"Liep iemand daar bij nacht, dan kon hij onverwachts een wit veulen in vliegende vaart zich voorbij zien snellen, waarna het plotseling verdween.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69795","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"DYKFRIES2156","role":"member","render":{"description":"Een boer uit Westdongeradeel had regelmatig ontmoetingen met een plaaggeest. Het dier liep steeds met hem mee naar huis, maar deed hem verder niets. De boer zorgde ervoor dat hij het dier altijd een stukje roggebrood kon aanbieden. Zijn dienstmeid beweerde dat zij dapperder zou zijn en dat ze als zij het dier tegenkwam, er wel op naar huis zou rijden. Toen zij het dier eens tegenkwam, zette het zijn voorpoten op haar schouders, waardoor de meid gedwongen was het gewicht van het dier mee te dragen op haar weg naar huis.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69345","original":"In Westdongeradeel woonde weleer een boer die veel last had van een plaagbeest. Was de man 's avonds bij duister op weg naar zijn huis, dan kwam hem meest altijd zulk een spookdier op zijde. Het vergezelde hem tot aan zijn erf. Eens zelfs was het meegegaan over het bruggetje, dat aan den weg over de gracht lag. Maar dat was dan ook alles; eigenlijk kwaad deed het hem niet. Hij zorgde altijd een stuk roggebrood bij zich te hebben, waarop hij 't beest dan onthaalde. Dit scheen daar smaak in te vinden, nam het gretig aan en liet den boer ongedeerd. Maar de man was toch altijd ontsteld als hij in huis kwam. Zijne dienstmeid vond dit wel wat dwaas en schroomde ook niet voor hare meening uit te komen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Broeksterwâld hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":2},"on_success":{"trail_note":1,"unlock_cabinet":2,"stack":["c2","c3","c4"]}},{"id":"4-3","type":"R4","difficulty":1.1273,"rank":0.375,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"LYST162","role":"top","render":{"description":"Vroeger zei men dat men niet in het midden van de weg moest lopen als het al donker was, want dan liep men het gevaar naar de kant van de weg of in de berm gesmeten te worden. Ook gebeurde het dat men door een hond gevolgd werd, die net zolang meeliep tot het huis was bereikt. In bosrijke gebieden gebeurde het wel","place":"Oranjewoud","prov":"Fr.","year":1957,"code":"SINSAG 0333","initials":"S.","url":"https://www.verhalenbank.nl/items/show/13413","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CJ010112","role":"half","render":{"description":"Het beest is heel groot en geel en het klapt met de oren. Het beest gaat vlak langs de man en blijft een tijdje bij hem. De man denkt dat het een plaagbeest is geweest.","half":"bottom","code":"SINSAG 0333"},"home":"4-3"},{"id":"c3","story_id":"LYST162","role":"bottom","render":{"description":"dat twee vurige ogen de mensen aankeken. Die ogen waren het \"Boze\", dat altijd op de loer lag.","half":"bottom","code":"SINSAG 0333","stain":"twee"},"home":"4-3"},{"id":"c4","story_id":"CJ080711","role":"half","render":{"description":"Midden op de weg stond er toen een hele grote hond, die hem niet voorbij liet. Dat was een plaagbeest. De man is weer terug gegaan.","half":"bottom","code":"SINSAG 0256"},"home":"4-3"},{"id":"c5","story_id":"CJ018108","role":"half","render":{"description":"Als de ratten rondrenden, hoorde je het geld rinkelen. Toen de plaats later afgebroken werd, hebben ze al het geld gevonden. Het was een spookplaats.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c6","story_id":"KEMP280","role":"half","render":{"description":"Ze brachten ongeluk aan wie hen weg wilde jagen. Dergelijke kettinghonden vertoonden zich vroeger ook in de omstreken van Broekhuizen, Broekhuizenvorst, Blitterswijk, Wanssum, Geysteren, Maashees en Venray. Te Blitterswijk noemde men hem de 'patershond' en men bleef liever bij hem uit de buurt.","half":"bottom","code":"SINSAG 0333"},"home":"4-3"},{"id":"c7","story_id":"CJ060905","role":"half","render":{"description":"Als Schopper, de directeur van de Wilhelminahoeve dit hoort gelooft hij het niet, maar hij moet toegeven dat ze gelijk heeft als ze het ook zelf zien.","half":"bottom","code":"SINSAG 0477"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","De machine stopt midden in een zin. Het vervolg maakt hem af.","Het nummer is SINSAG 0333. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c3","object":"typewriter"},"on_success":{"fuse":["c1","c3"],"type_line":"Verteller: de vorige assistent.","digit":{"value":2,"card":"c1","word":"twee","stained":"c3"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
